function json(data, status = 200, headers = {}) {
  return new Response(JSON.stringify(data), { status, headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store", ...headers } });
}
function b64url(bytes) {
  let s = ""; for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}
function fromB64url(value) {
  const raw = atob(value.replace(/-/g, "+").replace(/_/g, "/") + "===".slice((value.length + 3) % 4));
  return Uint8Array.from(raw, c => c.charCodeAt(0));
}
function bytesFromB64(value) { const raw = atob(value); return Uint8Array.from(raw, c => c.charCodeAt(0)); }
async function hmacKey(secret) { return crypto.subtle.importKey("raw", encoder.encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign", "verify"]); }
async function signSession(user, env) {
  if (!env.SESSION_SECRET) throw new Error("SESSION_SECRET ontbreekt in de Worker-configuratie.");
  const payload = b64url(encoder.encode(JSON.stringify({ sub: user.id, email: user.email, exp: Math.floor(Date.now() / 1000) + 60 * 60 * 24 * 7 })));
  const signature = new Uint8Array(await crypto.subtle.sign("HMAC", await hmacKey(env.SESSION_SECRET), encoder.encode(payload)));
  return `${payload}.${b64url(signature)}`;
}
async function readSession(request, env) {
  const cookie = request.headers.get("cookie") || "";
  const token = cookie.split(";").map(x => x.trim()).find(x => x.startsWith("session="))?.slice(8);
  if (!token || !env.SESSION_SECRET) return null;
  const [payload, signature] = token.split("."); if (!payload || !signature) return null;
  try {
    const ok = await crypto.subtle.verify("HMAC", await hmacKey(env.SESSION_SECRET), fromB64url(signature), encoder.encode(payload));
    if (!ok) return null;
    const data = JSON.parse(decoder.decode(fromB64url(payload)));
    if (!data.sub || data.exp < Math.floor(Date.now() / 1000)) return null;
    const user = await env.DB.prepare("SELECT id,email,name,picture FROM users WHERE id = ?").bind(data.sub).first();
    return user || null;
  } catch { return null; }
}
async function requireUser(request, env) {
  const email = (request.headers.get("Cf-Access-Authenticated-User-Email") || "").trim().toLowerCase();
  if (!email || !email.includes("@")) throw Object.assign(new Error("Aanmelden via Cloudflare Access is vereist."), { status: 401 });
  let user = await env.DB.prepare("SELECT id,email,name,picture FROM users WHERE lower(email)=?").bind(email).first();
  const time = now();
  if (!user) { const id = "access:" + email; const displayName = email === "arne.nys@ptiz.be" ? "Arne Nys" : email.split("@")[0].replaceAll(".", " ").replaceAll("_", " "); await env.DB.prepare("INSERT OR IGNORE INTO users (id,email,name,picture,created_at,last_login_at) VALUES (?,?,?,NULL,?,?)").bind(id,email,displayName,time,time).run(); user = await env.DB.prepare("SELECT id,email,name,picture FROM users WHERE lower(email)=?").bind(email).first(); } else { await env.DB.prepare("UPDATE users SET last_login_at=? WHERE id=?").bind(time,user.id).run(); }
  const token=request.headers.get("Cf-Access-Jwt-Assertion")||"";let ar;try{ar=await fetch("https://sapoov-identity-api.arne-nys.workers.dev/api/access/examenmaker",{headers:{"Cf-Access-Jwt-Assertion":token}})}catch{throw Object.assign(new Error("SAPOOV-rechtenservice tijdelijk niet bereikbaar."),{status:503})}const access=await ar.json().catch(()=>({}));if(!ar.ok||!access.authorized)throw Object.assign(new Error(access.error||"Geen centrale toegang tot Examenmaker."),{status:403});const permissions=[...new Set((access.roles||[]).flatMap(r=>r.permissions||[]))];return {...user,permissions,centralRoles:access.roles||[],isSuperadmin:permissions.includes("*"),authProvider:"Cloudflare Access"};
}
function cookie(value, maxAge) { return `session=${value}; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=${maxAge}`; }
async function bodyJson(request) { try { return await request.json(); } catch { throw Object.assign(new Error("De request bevat geen geldige JSON."), { status: 400 }); } }
function now() { return new Date().toISOString(); }
function safeFilename(value) { return String(value || "examen").normalize("NFKD").replace(/[^a-zA-Z0-9_-]+/g, "_").replace(/^_+|_+$/g, "").slice(0, 70) || "examen"; }

async function authLogin(request, env) {
  if (!env.GOOGLE_CLIENT_ID) return json({ error: "Google-aanmelding is nog niet geconfigureerd." }, 503);
  const { credential } = await bodyJson(request);
  if (!credential || typeof credential !== "string" || credential.length > 10000) return json({ error: "Google-token ontbreekt of is ongeldig." }, 400);
  const check = await fetch("https://oauth2.googleapis.com/tokeninfo?id_token=" + encodeURIComponent(credential));
  if (!check.ok) return json({ error: "Google kon de aanmelding niet verifiëren." }, 401);
  const identity = await check.json();
  if (identity.aud !== env.GOOGLE_CLIENT_ID || identity.email_verified !== "true" || !identity.email) return json({ error: "Het Google-account kon niet worden geverifieerd." }, 401);
  const allowed = (env.ALLOWED_EMAIL_DOMAINS || "").split(",").map(x => x.trim().toLowerCase()).filter(Boolean);
  const domain = identity.email.toLowerCase().split("@").pop();
  if (allowed.length && !allowed.includes(domain)) return json({ error: "Dit Google-account heeft geen toegang tot de Examenmaker." }, 403);
  const id = identity.sub;
  const displayName = identity.name || identity.given_name || identity.email;
  const picture = identity.picture || null;
  const time = now();
  await env.DB.prepare(`INSERT INTO users (id,email,name,picture,created_at,last_login_at) VALUES (?,?,?,?,?,?)
    ON CONFLICT(id) DO UPDATE SET email=excluded.email,name=excluded.name,picture=excluded.picture,last_login_at=excluded.last_login_at`)
    .bind(id, identity.email, displayName, picture, time, time).run();
  const user = { id, email: identity.email, name: displayName, picture };
  const session = await signSession(user, env);
  return json({ user }, 200, { "set-cookie": cookie(session, 60 * 60 * 24 * 7) });
}

async function sapoFetch(path, init, env) {
  if (!env.SAPO_API_KEY) throw Object.assign(new Error("De SAPO API-sleutel is niet ingesteld als Worker-secret."), { status: 503 });
  const url = "https://classid.io/api" + path;
  const response = await fetch(url, { ...init, headers: { "api-key": env.SAPO_API_KEY, "content-type": "application/json", ...(init?.headers || {}) } });
  const text = await response.text();
  if (!response.ok) throw Object.assign(new Error(`SAPO API antwoordde met status ${response.status}. ${text.slice(0, 300)}`), { status: 502 });
  try { return JSON.parse(text); } catch { throw Object.assign(new Error("De SAPO API gaf geen geldige JSON terug."), { status: 502 }); }
}

async function examById(id, userId, env) {
  const row = await env.DB.prepare("SELECT id,title,payload_json,created_at,updated_at FROM exams WHERE id=? AND user_id=?").bind(id, userId).first();
  if (!row) throw Object.assign(new Error("Examen niet gevonden."), { status: 404 });
  return { id: row.id, title: row.title, payload: JSON.parse(row.payload_json), createdAt: row.created_at, updatedAt: row.updated_at };
}
async function listExams(user, env) {
  const { results } = await env.DB.prepare("SELECT id,title,payload_json,created_at,updated_at FROM exams WHERE user_id=? ORDER BY updated_at DESC").bind(user.id).all();
  return results.map(row => { const p = JSON.parse(row.payload_json); return { id: row.id, title: row.title, subject: p.heading?.subject || "", schoolYear: p.heading?.schoolYear || "", createdAt: row.created_at, updatedAt: row.updated_at }; });
}
async function saveExam(request, user, env) {
  const data = await bodyJson(request);
  if (!Array.isArray(data.questions) || data.questions.length < 1 || data.questions.length > 100) return json({ error: "Een examen moet minstens één en maximaal 100 vragen bevatten." }, 400);
  const id = data.id || crypto.randomUUID();
  const title = String(data.title || data.heading?.subject || "Nieuw examen").slice(0, 180);
  const legacyPlanId = data.planId || data.questions.find(q => q.planId)?.planId || "";
  if (!legacyPlanId) return json({ error: "Selecteer eerst het leerplan voor dit examen." }, 400);
  const visibleErrorIds = Array.isArray(data.visibleErrorIds)
    ? [...new Set(data.visibleErrorIds.filter(id => ERROR_LIBRARY.some(item => item.id === id)))].slice(0, ERROR_LIBRARY.length)
    : ERROR_LIBRARY.map(item => item.id);
  const payload = { planId: String(legacyPlanId), planLabel: String(data.planLabel || "").slice(0, 500), heading: data.heading || {}, questions: data.questions.map(q => { const questionType = q.questionType === "vraagstuk" ? "vraagstuk" : "lang-invulantwoord"; return { questionType, text: String(q.text || "").slice(0, 12000), maxScore: questionType === "vraagstuk" ? 5 : Math.max(0, Number(q.maxScore) || 0), goalIds: Array.isArray(q.goalIds) ? q.goalIds.slice(0, 30) : [], sapoGoals: Array.isArray(q.sapoGoals) ? q.sapoGoals.slice(0, 30) : [], answerKey: String(q.answerKey || "").slice(0, 12000), answerSpaceLines: questionType === "lang-invulantwoord" ? Math.max(1, Math.min(12, Number(q.answerSpaceLines) || 3)) : 0 }; }), selfEvaluation: Array.isArray(data.selfEvaluation) ? data.selfEvaluation.filter(x => /^s_\d+_\d+$/.test(x)) : [], visibleErrorIds };
  const time = now();
  await env.DB.prepare(`INSERT INTO exams(id,user_id,title,payload_json,created_at,updated_at) VALUES(?,?,?,?,?,?)
    ON CONFLICT(id) DO UPDATE SET title=excluded.title,payload_json=excluded.payload_json,updated_at=excluded.updated_at WHERE exams.user_id=excluded.user_id`)
    .bind(id, user.id, title, JSON.stringify(payload), time, time).run();
  const row = await env.DB.prepare("SELECT id FROM exams WHERE id=? AND user_id=?").bind(id, user.id).first();
  if (!row) return json({ error: "Je mag dit examen niet aanpassen." }, 403);
  return json({ exam: { id, title, payload, updatedAt: time } });
}

function x(text) { return String(text ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&apos;"); }
function wRun(text, options = {}) {
  const props = `<w:rPr>${options.bold ? "<w:b/><w:bCs/>" : ""}${options.color ? `<w:color w:val="${options.color}"/>` : ""}<w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:sz w:val="${options.size || 20}"/><w:szCs w:val="${options.size || 20}"/></w:rPr>`;
  return `<w:r>${props}<w:t xml:space="preserve">${x(text)}</w:t></w:r>`;
}
function wP(text = "", options = {}) {
  const parts = String(text).split("\n").map((line, i) => (i ? "<w:r><w:br/></w:r>" : "") + wRun(line, options)).join("");
  return `<w:p><w:pPr><w:spacing w:after="${options.after ?? 80}" w:line="${options.line || 240}" w:lineRule="auto"/>${options.align ? `<w:jc w:val="${options.align}"/>` : ""}</w:pPr>${parts || "<w:r><w:t></w:t></w:r>"}</w:p>`;
}
function wBlankLine() { return `<w:p><w:pPr><w:spacing w:after="20" w:line="260" w:lineRule="exact"/><w:pBdr><w:bottom w:val="single" w:sz="2" w:space="1" w:color="B7B7B7"/><w:between w:val="single" w:sz="2" w:space="1" w:color="B7B7B7"/></w:pBdr></w:pPr><w:r><w:t xml:space="preserve"> </w:t></w:r></w:p>`; }
function wCell(content, width, opts = {}) {
  const paras = Array.isArray(content) ? content : [String(content ?? "")];
  const padding = opts.padding ?? 65;
  const inner = paras.map(p => {
    if (p && typeof p === "object" && p.part) {
      const label = wP(`${p.label} (${p.points} ${p.points === 1 ? "punt" : "punten"})`, { size: opts.size || 18, bold: true, after: 10, line: 220 });
      return label + Array.from({ length: p.lines || 1 }, () => wBlankLine()).join("");
    }
    return typeof p === "object" && p.blank ? wBlankLine() : wP(typeof p === "object" ? p.text : p, { size: opts.size || 18, bold: opts.bold || false, align: opts.align, after: opts.after ?? 35, line: opts.line ?? 240, color: opts.color });
  }).join("");
  return `<w:tc><w:tcPr><w:tcW w:w="${width}" w:type="dxa"/>${opts.bg ? `<w:shd w:fill="${opts.bg}"/>` : ""}<w:vAlign w:val="${opts.vAlign || "center"}"/><w:tcMar><w:top w:w="${padding}" w:type="dxa"/><w:left w:w="${opts.leftPadding ?? 70}" w:type="dxa"/><w:bottom w:w="${padding}" w:type="dxa"/><w:right w:w="${opts.leftPadding ?? 70}" w:type="dxa"/></w:tcMar></w:tcPr>${inner}</w:tc>`;
}
function wTable(rows, widths, options = {}) {
  const borders = `<w:tblBorders><w:top w:val="single" w:sz="${options.border || 6}" w:color="000000"/><w:left w:val="single" w:sz="${options.border || 6}" w:color="000000"/><w:bottom w:val="single" w:sz="${options.border || 6}" w:color="000000"/><w:right w:val="single" w:sz="${options.border || 6}" w:color="000000"/><w:insideH w:val="single" w:sz="${options.border || 6}" w:color="000000"/><w:insideV w:val="single" w:sz="${options.border || 6}" w:color="000000"/></w:tblBorders>`;
  const grid = widths.map(w => `<w:gridCol w:w="${w}"/>`).join("");
  const body = rows.map((row, ri) => `<w:tr>${(options.rowHeight && ri > 0) || (options.repeatHeader && ri === 0) ? `<w:trPr>${options.repeatHeader && ri === 0 ? `<w:tblHeader w:val="true"/>` : ""}${options.rowHeight && ri > 0 ? `<w:trHeight w:val="${options.rowHeight}" w:hRule="atLeast"/>` : ""}${options.cantSplit && ri > 0 ? "<w:cantSplit/>" : ""}</w:trPr>` : ""}${row.map((cell, ci) => { const c = typeof cell === "object" && !Array.isArray(cell) ? cell : { text: cell }; return wCell(c.lines || c.text || "", widths[ci], { bg: c.bg || (options.header && ri === 0 ? "D9D9D9" : ""), bold: c.bold || (options.header && ri === 0), align: c.align || (options.header && ri === 0 ? "center" : "left"), size: c.size || options.size || 18, color: c.color, padding: options.padding, leftPadding: options.leftPadding, after: options.after, line: options.line, vAlign: options.vAlign }); }).join("")}</w:tr>`).join("");
  return `<w:tbl><w:tblPr><w:tblW w:w="${widths.reduce((a,b)=>a+b,0)}" w:type="dxa"/><w:tblLayout w:type="fixed"/>${borders}<w:tblCellMar><w:top w:w="45" w:type="dxa"/><w:left w:w="60" w:type="dxa"/><w:bottom w:w="45" w:type="dxa"/><w:right w:w="60" w:type="dxa"/></w:tblCellMar></w:tblPr><w:tblGrid>${grid}</w:tblGrid>${body}</w:tbl>`;
}
function headingTable(h, totalScore = 0) {
  const disorder = ["Dyslexie", "Dyscalculie", "Dysorthografie", "Andere: ……………"].join("\n□ ");
  return wTable([
    [{ text: `Schooljaar: ${h.schoolYear || ""}\nDatum: ${h.date || ""}`, size: 19, align: "right" }, { text: `Trimester: ${h.trimester || ""}`, size: 19, align: "right" }],
    [{ text: `Vak: ${h.subject || ""}\nLeerkracht: ${h.teacher || ""}\nKlassen: ${h.classes || ""}\nNaam leerling: …………………………………………………………………`, size: 19 }, { text: `□ ${disorder}`, size: 17 }],
    [{ text: "", size: 18 }, { text: `Score\n/ ${totalScore}`, size: 25, bold: true, align: "center" }]
  ], [6200, 2300], { border: 0, size: 19 });
}
function selectedSelfItems(payload) {
  const ids = new Set(payload.selfEvaluation || []); const groups = [];
  SELF_EVAL.forEach((g, gi) => { const items = g.items.map((text, ii) => ({ id: `s_${gi}_${ii}`, text })).filter(it => ids.has(it.id)); if (items.length) groups.push({ title: g.title, section: g.section || "", items }); });
  return groups;
}
function wordPreview(text) {
  const words = String(text || "").trim().split(/\s+/).filter(Boolean).slice(0, 5);
  return words.join(" ") + "...";
}
function questionGoals(q) {
  const seen = new Set();
  return (q.sapoGoals || []).map(g => String(g.label || g.id || "").trim()).filter(label => {
    if (!label || seen.has(label)) return false;
    seen.add(label); return true;
  });
}
function selectedErrorLibraryItems(payload) {
  // Oudere examens zonder selectieveld behouden de vroegere standaard: alle fouten tonen.
  if (!Array.isArray(payload.visibleErrorIds)) return ERROR_LIBRARY;
  const selected = new Set(payload.visibleErrorIds);
  return ERROR_LIBRARY.filter(item => selected.has(item.id));
}
function sectionProperties(orientation = "portrait", sectionType = null) {
  const landscape = orientation === "landscape";
  return `<w:sectPr>${sectionType ? `<w:type w:val="${sectionType}"/>` : ""}<w:headerReference w:type="default" r:id="rId1"/><w:footerReference w:type="default" r:id="rId2"/><w:pgSz w:w="${landscape ? 16838 : 11906}" w:h="${landscape ? 11906 : 16838}"${landscape ? ' w:orient="landscape"' : ""}/><w:pgMar w:top="850" w:right="850" w:bottom="850" w:left="1050" w:header="360" w:footer="360" w:gutter="0"/></w:sectPr>`;
}
function nextLandscapeSectionParagraph() {
  return `<w:p><w:pPr>${sectionProperties("portrait", "nextPage")}</w:pPr><w:r><w:t></w:t></w:r></w:p>`;
}
function buildDocumentXml(exam, correction = false) {
  const p = exam.payload; const h = p.heading || {}; const qs = p.questions || [];
  const totalScore = qs.reduce((sum, q) => sum + (Number(q.maxScore) || 0), 0);
  let body = `<w:p><w:pPr><w:spacing w:after="120"/></w:pPr></w:p>${headingTable(h, totalScore)}`;
  if (correction) body += wP("Verbetersleutel", { size: 22, bold: true, after: 75 });
  else body += wP("", {after:50});
  const rows = [[{text:"Nr.",align:"center"},{text:correction?"Examenvragen en verbetersleutel":"Examenvragen",align:"center"},{text:"Punten per vraag",align:"center"},{text:"Nr. SAPO-doel",align:"center"}]];
  qs.forEach((q,i)=>{
    const goalText = (q.sapoGoals || []).map(g => g.label || g.id).join("\n");
    const questionLines = [q.text || ""];
    if (correction) {
      if (q.questionType === "vraagstuk") questionLines.push("Puntenverdeling: Gegevens 1 punt · Gevraagd 1 punt · Oplossingsmethode 2 punten · Antwoordzin 1 punt.");
      questionLines.push("Verbetersleutel / evaluatiecriteria:", q.answerKey || "(Nog geen verbetersleutel ingevuld.)");
    }
    else if (q.questionType === "vraagstuk") {
      questionLines.push(
        { part: true, label: "Gegevens", points: 1, lines: 1 },
        { part: true, label: "Gevraagd", points: 1, lines: 1 },
        { part: true, label: "Oplossingsmethode", points: 2, lines: 3 },
        { part: true, label: "Antwoordzin", points: 1, lines: 1 }
      );
    } else for(let n=0;n<Math.min(12,Number(q.answerSpaceLines)||3);n++) questionLines.push({blank:true});
    rows.push([{text:String(i+1),align:"center",size:18},{lines:questionLines,size:18},{text:`/ ${q.maxScore ?? 0}`,align:"center",size:18},{text:goalText,align:"center",size:16}]);
  });
  rows[0][0].bg = "D9D9D9";
  body += wTable(rows, [620, 6200, 1000, 900], { header: true, size: 18 });
  body += wP(correction ? `Totaal: ${qs.reduce((s,q)=>s+(Number(q.maxScore)||0),0)} punten` : "Veel succes!", { size: 20, after: 120 });
  if (!correction) {
    body += `<w:p><w:r><w:br w:type="page"/></w:r></w:p>`;
    body += wP("Zelfevaluatie", { size: 22, bold: true, after: 40 });
    body += wP("Hoe verliep de voorbereiding van het examen?", { size: 20, bold: true, after: 75 });
    const selfRows = [[{text:"",bg:"D9D9D9"},{text:"ja",bg:"D9D9D9",align:"center"},{text:"neen",bg:"D9D9D9",align:"center"},{text:"Opmerking",bg:"D9D9D9",align:"center"}]];
    for (const g of selectedSelfItems(p)) {
      if (g.section) selfRows.push([{text:g.section,bold:true,bg:"D9D9D9",size:19},{text:"",bg:"D9D9D9"},{text:"",bg:"D9D9D9"},{text:"",bg:"D9D9D9"}]);
      selfRows.push([{text:g.title,bold:true,bg:"EFEFEF",size:17},{text:"",bg:"EFEFEF"},{text:"",bg:"EFEFEF"},{text:"",bg:"EFEFEF"}]);
      for (const item of g.items) {
        if (item.id === "s_4_4") selfRows.push([{text:"Hoe lang heb je (ongeveer) gestudeerd voor je examen?",size:16},{text:""},{text:""},{text:""}]);
        selfRows.push([{text:item.text,size:16},{text:""},{text:""},{text:""}]);
      }
      if (g.title === "Studietiming" && !g.items.some(item => item.id === "s_4_4")) selfRows.push([{text:"Hoe lang heb je (ongeveer) gestudeerd voor je examen?",size:16},{text:""},{text:""},{text:""}]);
    }
    body += wTable(selfRows, [6100, 750, 750, 900], { size: 14, border: 4, padding: 15, leftPadding: 55, after: 0, line: 170 });

    // Foutenanalyse: eigen A4-landscape-sectie, na alle zelfevaluatiepagina's.
    body += nextLandscapeSectionParagraph();
    body += headingTable(h, totalScore);
    body += wP("Foutenanalyse", { size: 22, bold: true, after: 55 });
    const errorRows = [[
      { text: "Vraagnummer", align: "center", size: 14, bg: "D9D9D9", bold: true },
      { text: "Vraag", align: "center", size: 14, bg: "D9D9D9", bold: true },
      { text: "Leerstofonderdeel/onderwerp", align: "center", size: 14, bg: "D9D9D9", bold: true },
      { text: "Doelen", align: "center", size: 14, bg: "D9D9D9", bold: true },
      { text: "Score", align: "center", size: 14, bg: "D9D9D9", bold: true },
      { text: "Soort fout", align: "center", size: 14, bg: "D9D9D9", bold: true },
      { text: "Actie", align: "center", size: 14, bg: "D9D9D9", bold: true }
    ]];
    qs.forEach((q, i) => {
      errorRows.push([
        { text: String(i + 1), align: "center", size: 13 },
        { text: wordPreview(q.text), size: 13 },
        { text: "", size: 13 },
        { text: questionGoals(q).join("\n"), size: 12 },
        { text: `/${q.maxScore ?? 0}`, align: "center", size: 13 },
        { text: "", size: 13 },
        { text: "", size: 13 }
      ]);
    });
    // 380 twips is half the previous minimum row height (760 twips).
    // Rows can grow when SAPO goals wrap, avoiding clipped text.
    body += wTable(errorRows, [1150, 2100, 2250, 4200, 650, 2050, 2100], {
      size: 13, border: 5, padding: 30, leftPadding: 45, after: 0, line: 170,
      rowHeight: 380, repeatHeader: true, vAlign: "top"
    });

    // Foutenbibliotheek: alleen de door de leerkracht aangevinkte items tonen.
    const visibleErrors = selectedErrorLibraryItems(p);
    if (visibleErrors.length) {
      body += wP("Foutenlijst en herstelacties", { size: 17, bold: true, after: 35 });
      const libraryRows = [[
        { text: "Fout", align: "center", size: 14, bg: "D9D9D9", bold: true },
        { text: "Foutcategorie", align: "center", size: 14, bg: "D9D9D9", bold: true },
        { text: "Herstelactie", align: "center", size: 14, bg: "D9D9D9", bold: true },
        { text: "Actietype", align: "center", size: 14, bg: "D9D9D9", bold: true }
      ]];
      for (const item of visibleErrors) {
        libraryRows.push([
          { text: item.fout, size: 13 },
          { text: item.foutcategorie, size: 13 },
          { text: item.herstelactie, size: 13 },
          { text: item.actietype, size: 13, align: "center" }
        ]);
      }
      body += wTable(libraryRows, [3200, 2600, 6800, 1900], {
        header: true, repeatHeader: true, cantSplit: true, size: 13, border: 4,
        padding: 28, leftPadding: 45, after: 12, line: 150,
        rowHeight: 280, vAlign: "center"
      });
    } else {
      body += wP("Er werden geen fouttypes geselecteerd voor de foutenlijst.", { size: 13, after: 35 });
    }
  }
  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"><w:body>${body}${correction ? sectionProperties("portrait") : sectionProperties("landscape")}</w:body></w:document>`;
}
