function pdfLine(x1,y1,x2,y2,color="#000000",width=.5){return `${pdfRGB(color)} RG ${width} w ${x1} ${y1} m ${x2} ${y2} l S\n`;}
function pdfRect(x,y,w,h,fill=null,stroke="#000000",width=.5){let s="q\n";if(fill)s+=`${pdfRGB(fill)} rg\n`;if(stroke)s+=`${pdfRGB(stroke)} RG ${width} w\n`;s+=`${x} ${y} ${w} ${h} re ${fill&&stroke?"B":fill?"f":"S"}\nQ\n`;return s;}
function pdfImage(name,x,y,w,h){return `q ${w} 0 0 ${h} ${x} ${y} cm /${name} Do Q\n`;}
function wrapText(text,maxChars){const out=[];for(const para of String(text??"").split(/\r?\n/)){if(!para){out.push("");continue;}let line="";for(const word of para.split(/\s+/)){if(!word)continue;if(line && (line+" "+word).length>maxChars){out.push(line);line=word;}else line+=(line?" ":"")+word;}out.push(line);}return out;}
