async function exportResponse(exam, correction, type) {
  const isDocx=type==="docx";const bytes=isDocx?createDocx(exam,correction):makeExamPdf(exam,correction);
  const filename=safeFilename(exam.title)+(correction?"-verbetersleutel":"-examen")+(isDocx?".docx":".pdf");
  return new Response(bytes,{headers:{"content-type":isDocx?"application/vnd.openxmlformats-officedocument.wordprocessingml.document":"application/pdf","content-disposition":`attachment; filename="${filename}"`,"cache-control":"no-store"}});
}
